import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"EmakiAttribute","description":"","frontmatter":{},"headers":[],"relativePath":"modules/attribute/index.md","filePath":"modules/attribute/index.md","lastUpdated":0}`),a={name:`modules/attribute/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="emakiattribute" tabindex="-1">EmakiAttribute <a class="header-anchor" href="#emakiattribute" aria-label="Permalink to “EmakiAttribute”">​</a></h1><p>EmakiAttribute 负责真实属性、资源和战斗结算。它定义 RPG 属性、伤害类型和条件，并为其他模块提供 PDC 属性 API。装备属性应写入 Attribute payload，而不是只写在 Lore 里。</p><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to “基本信息”">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>模块版本</td><td><code>4.8.1</code></td></tr><tr><td>主命令</td><td><code>/emakiattribute</code></td></tr><tr><td>别名</td><td><code>/eattribute</code>、<code>/ea</code></td></tr><tr><td>硬依赖</td><td>EmakiCoreLib</td></tr><tr><td>软依赖</td><td>MythicMobs、PlaceholderAPI、MMOItems、BetterHUD</td></tr><tr><td>默认权限</td><td><code>emakiattribute.use</code>、<code>emakiattribute.points</code> 默认 true；其余管理权限默认 op</td></tr></tbody></table><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to “它解决什么问题”">​</a></h2><p>当原版属性不足以表达 RPG 战斗时，可以用 EmakiAttribute 定义自己的属性和伤害逻辑，例如：</p><ul><li>物理攻击、法术攻击、投射物攻击。</li><li>物理防御、法术防御、投射物防御。</li><li>暴击率、暴击伤害、暴击抵抗。</li><li>护甲穿透、法术穿透、真实伤害。</li><li>生命、法力、生命恢复、法力恢复。</li><li>闪避、吸血、攻速、移动速度、原版属性映射。</li></ul><p>这些属性可以来自 Item、Forge、Strengthen、Gem、Skills 或其他模块写入的 PDC。Attribute 负责汇总和计算，而不是让其他插件各自重复实现一套数值系统。</p><h2 id="默认配置目录" tabindex="-1">默认配置目录 <a class="header-anchor" href="#默认配置目录" aria-label="Permalink to “默认配置目录”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/EmakiAttribute/</span></span>
<span class="line"><span>├── config.yml</span></span>
<span class="line"><span>├── attribute_balance.yml</span></span>
<span class="line"><span>├── attributes/</span></span>
<span class="line"><span>├── conditions/</span></span>
<span class="line"><span>├── damage_types/</span></span>
<span class="line"><span>├── lore_formats/</span></span>
<span class="line"><span>├── presets/</span></span>
<span class="line"><span>├── gui/</span></span>
<span class="line"><span>├── lang/</span></span>
<span class="line"><span>└── data/</span></span></code></pre></div><p>目录说明：</p><table tabindex="0"><thead><tr><th>目录 / 文件</th><th>作用</th></tr></thead><tbody><tr><td><code>attributes/</code></td><td>每个属性的定义。</td></tr><tr><td><code>damage_types/</code></td><td>伤害类型，例如 physical、projectile、spell。</td></tr><tr><td><code>conditions/</code></td><td>属性读取条件（PDC 读取规则）定义。</td></tr><tr><td><code>lore_formats/</code></td><td>属性在 Lore 中的展示格式。</td></tr><tr><td><code>attribute_balance.yml</code></td><td>属性平衡语义与战力权重配置。</td></tr><tr><td><code>presets/</code></td><td>属性预设定义。</td></tr><tr><td><code>gui/</code></td><td>属性点 GUI 配置（<code>attribute_points.yml</code>）。</td></tr><tr><td><code>lang/</code></td><td>语言文件（内置 <code>zh_CN.yml</code>、<code>en_US.yml</code>）。</td></tr><tr><td><code>data/</code></td><td>运行时数据，例如 <code>data/parent_attributes/&lt;UUID&gt;.yml</code>。</td></tr></tbody></table><h2 id="典型工作流" tabindex="-1">典型工作流 <a class="header-anchor" href="#典型工作流" aria-label="Permalink to “典型工作流”">​</a></h2><ol><li>在 <code>attributes/</code> 中定义属性。</li><li>在 <code>lore_formats/</code> 中定义展示格式。</li><li>在 <code>damage_types/</code> 中定义伤害类型如何计算。</li><li>让 Item / Forge / Strengthen / Gem 等模块写入属性 payload。</li><li>玩家装备变化或执行同步后，Attribute 汇总属性。</li><li>战斗发生时，根据伤害类型、攻击方属性、防御方属性计算结果。</li><li>通过消息、ActionBar、PAPI 或 debug 输出结果。</li></ol><h2 id="与其他模块的关系" tabindex="-1">与其他模块的关系 <a class="header-anchor" href="#与其他模块的关系" aria-label="Permalink to “与其他模块的关系”">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>协作方式</th></tr></thead><tbody><tr><td>EmakiItem</td><td>自定义物品可以携带基础属性和套装属性。</td></tr><tr><td>EmakiForge</td><td>锻造结果可写入额外属性。</td></tr><tr><td>EmakiStrengthen</td><td>强化星级可增加属性。</td></tr><tr><td>EmakiGem</td><td>宝石可提供属性。</td></tr><tr><td>EmakiSkills</td><td>技能释放可读取或消耗 Attribute 资源，也可检查属性门槛。</td></tr><tr><td>MythicMobs</td><td>可作为技能或怪物战斗生态的一部分。</td></tr><tr><td>PlaceholderAPI</td><td>对外展示玩家属性、资源或战斗数据。</td></tr></tbody></table><h2 id="功能页面" tabindex="-1">功能页面 <a class="header-anchor" href="#功能页面" aria-label="Permalink to “功能页面”">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>内容</th></tr></thead><tbody><tr><td><a href="./configuration.html">配置目录</a></td><td>主配置、属性目录、伤害目录、条件目录和排查顺序。</td></tr><tr><td><a href="./attributes.html">属性定义</a></td><td>属性字段、展示格式和属性 ID 设计。</td></tr><tr><td><a href="./scaling-curves.html">属性衰减曲线</a></td><td>高数值属性的阈值、曲线和调参建议。</td></tr><tr><td><a href="./damage.html">伤害系统</a></td><td>多阶段伤害管线、hard lock、命中反馈和恢复配置。</td></tr><tr><td><a href="./conditions.html">条件系统</a></td><td>装备条件、属性条件与跨模块条件。</td></tr><tr><td><a href="./lore-formats.html">Lore 格式</a></td><td>Lore 展示模板与读取正则。</td></tr><tr><td><a href="./commands.html">命令与权限</a></td><td><code>/ea</code> 命令、lint、preview、dump、source、trace 和调试。</td></tr><tr><td><a href="./placeholders.html">占位符</a></td><td>PlaceholderAPI 输出与伤害消息模板变量。</td></tr><tr><td><a href="./mythic.html">MythicMobs 集成</a></td><td>属性伤害 mechanic、临时属性 mechanic 与属性条件。</td></tr><tr><td><a href="./corelib-actions.html">CoreLib 动作</a></td><td>Attribute 注册的 Action ID 与参数。</td></tr><tr><td><a href="./api.html">API</a></td><td><code>EmakiAttributeApi</code>、<code>PdcAttributeAccess</code> 与接入约定。</td></tr><tr><td><a href="./events.html">事件 API</a></td><td>对外公开的 Bukkit 事件。</td></tr><tr><td><a href="./damage-event.html">伤害事件 API</a></td><td><code>EmakiAttributeDamageEvent</code> 详解。</td></tr></tbody></table><h2 id="建议配置顺序" tabindex="-1">建议配置顺序 <a class="header-anchor" href="#建议配置顺序" aria-label="Permalink to “建议配置顺序”">​</a></h2><ol><li>先使用默认属性启动服务器，确认模块正常加载。</li><li>添加或修改一个属性文件，执行 reload / lint 检查。</li><li>让一个测试物品写入该属性。</li><li>使用 preview / dump 命令确认属性被读取。</li><li>再接入伤害类型和战斗测试。</li></ol><h2 id="config-yml" tabindex="-1">config.yml <a class="header-anchor" href="#config-yml" aria-label="Permalink to “config.yml”">​</a></h2><p>主配置的完整字段清单、发货默认值与可复制示例见<a href="./configuration.html">配置目录</a>。常用小节的作用：</p><ul><li><code>default_profile</code>：玩家默认资源与属性基础值。</li><li><code>attribute_sources</code>：物品属性是否从 Lore / PDC 读取以及是否要求双来源一致。</li><li><code>vanilla_event_damage</code>：原版伤害是完美接管还是兼容重施。</li><li><code>shield</code>：盾牌格挡由原版还是 EA 结算。</li><li><code>allowed_damage_causes</code>：原版 <code>DamageCause</code> 到属性伤害类型的映射白名单。</li><li><code>scaling_curves</code>：属性超过阈值后的衰减规则，默认为空。</li></ul><h2 id="attribute-注册的动作" tabindex="-1">Attribute 注册的动作 <a class="header-anchor" href="#attribute-注册的动作" aria-label="Permalink to “Attribute 注册的动作”">​</a></h2><p>EmakiAttribute 会向 CoreLib 动作系统注册属性伤害、临时属性、资源、标签和同步动作。完整 Action ID、参数和示例已拆分到 <a href="./corelib-actions.html">CoreLib 动作</a>。</p><p>常用示例：</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;attribute_damage amount=50 type=physical&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;attribute_add effect_id=forge_buff attribute=physical_attack value=20 duration_ticks=10s&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;attribute_resource_consume resource=mana amount=20&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;attribute_sync all=false&#39;</span></span></code></pre></div>`,27)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};